// Guitar Cards — voicings content library (domain prefix voi-)
// Triads (close/spread), drop 2/3/2&4/2&3/4, shells, guide tones, rootless, quartal,
// Greene chord scales (major, melodic minor, harmonic minor, harmonic major),
// Goodrick & Miller voice-leading cycles, upper-structure triads, chord-melody basics,
// and theory quizzes about voicings. Plain object literals only; see docs/SCHEMA.md.
// Research notes and curriculum ladder: research/voicings.md

