    explain: "### Symmetry\nAn **augmented** triad splits the octave into three major 3rds (4 + 4 + 4 semitones). Every inversion is another augmented triad: C+ = E+ = G#+. The same shape repeats every 4 frets, and only four different augmented triads exist (C+, D♭+, D+, E♭+).\n\nA **diminished** triad (3 + 3 semitones) is not symmetric inside the octave. Its inversions are three different shapes. It works as a rootless dominant: B-D-F is G7 without the G, so Bdim resolves to C.",
