    explain: "### Spread triads\nTake a close triad and drop its **middle** voice an octave. That is the triad version of drop 2. The result spans a 10th or more and has the open, piano-like sound of modern jazz guitar.\n\n| close | spread result |\n|---|---|\n| 5-1-3 (2nd inv) | **1-5-3** (root position) |\n| 1-3-5 (root) | **3-1-5** (1st inversion) |\n| 3-5-1 (1st inv) | **5-3-1** (2nd inversion) |\n\nBecause the notes are more than an octave apart, they need a string skip: 6-4-3, 5-3-2, 4-2-1 (skip below) or 6-5-3, 5-4-2 (skip above). On 5-3-2, root position needs a big stretch, so it is left out of this drill's string sets.",
