    explain: "### Chord qualities as one-voice moves\nIn the spirit of Ted Greene's *Chord Chemistry*: keep one grip, and each quality is a half-step move of a single voice.\n\n| chord | 1 | 3 | 5 | 7 |\n|---|---|---|---|---|\n| maj7 | 1 | 3 | 5 | 7 |\n| 7 | 1 | 3 | 5 | **b7** |\n| m7 | 1 | **b3** | 5 | b7 |\n| m7b5 | 1 | b3 | **b5** | b7 |\n| dim7 | 1 | b3 | b5 | **bb7** |\n\nOnce you can do this in every inversion, one set of four drop 2 shapes covers five chord types.",
    visual: { type: "progression", key: "$root", chart: "$inversion", voicing: "drop2", stringSet: "$stringSet", voiceLead: true, startFret: 8 },
