    explain: "### The dim7 machine\nA diminished 7th divides the octave into four minor 3rds. All its inversions are the same shape, and Cdim7 = E♭dim7 = G♭dim7 = Adim7, so there are only three different dim7 chords.\n\nThe chord is also a hub:\n- **Lower any note a half step** and you get a dominant 7 rooted on that new note. From Cdim7 that gives B7, D7, F7 and A♭7.\n- **Bdim7 = G7b9 without its root.** Each dim7 is a rootless 7b9 for four dominants.\n\nBoth Ted Greene and Pat Martino make heavy use of this symmetry.",
