    id: "voi-drop2-ii-V-I",
    mode: "play",
    category: "voicings",
    tags: ["drop2", "ii-V-I", "voice-leading", "comping"],
    title: "Drop 2 ii–V–I in {key} on {stringSet}",
    level: 5,
    length: "medium",
    minutes: 3,
    params: {
      key: "major",
      stringSet: [{ v: [4, 3, 2, 1], lvl: 0 }, { v: [5, 4, 3, 2], lvl: 0 }, { v: [6, 5, 4, 3], lvl: 1 }],
    },
    prompt: "Play ii–V–I in **{key}** with drop 2 on strings **{stringSet}**, voice-led. Pass 1: ii in root position. Pass 2: ii in 1st inversion. Pass 3: 2nd. Pass 4: 3rd. Each pass stays in one area of the neck.",
    goal: "Two voices hold and two fall by step at each change. Your hand moves two frets at most.",
    tempo: { start: 72, min: 50, max: 180, step: 5, unit: "bpm" },
