    hints: [
      "The b5 of iiø and the b9 of V are the same note (in C minor: A♭). Hold it.",
      "Resolutions to i: 3 of V → root, b7 of V → b3, b9 of V → 5.",
      "The V7b9 shown has no 5th (the engine drops it to fit four strings).",
    ],
    explain: "### Minor ii–V–i\nThe minor ii–V–i takes its iiø7 and V7b9 from harmonic minor. Their shared notes make it smooth: the b3 of ii is the b7 of V, and the b5 of ii is the b9 of V. Into the tonic:\n- 3 of V (leading tone) → root of i\n- b7 of V → b3 of i\n- b9 of V → 5 of i\n\nFor the i chord, m6 and mMaj7 are the classic tonic sounds. A plain m7 sounds more Dorian.",
