    explain: "### Drop 3\nDrop 3 lowers the 3rd voice from the top an octave. The bass ends up a 6th or 7th below the next voice and more than an octave below the top two, so it needs a skipped string. The result is a bass note plus a close three-note chord. It is the shape behind classic root-on-6 jazz chords, chord melody with a real bass line, and walking-bass comping.\n\n| inversion | bottom → top | top note |\n|---|---|---|\n| root | 1-7-3-5 | 5 |\n| 1st | 3-1-5-7 | 7 |\n| 2nd | 5-3-7-1 | 1 |\n| 3rd | 7-5-1-3 | 3 |",
