    explain: "### Quartal chord scales\nGoodrick and Miller apply their cycles to quartal voicings in melodic minor (a Keyboard magazine excerpt from the Almanac shows cycles 2, 4 and 6 on a melodic-minor quartal voicing). Start with the stepwise version (cycle 2): stack diatonic 4ths on every scale degree and walk the voicing up the scale.\n\nMost diatonic 4ths are perfect, but some are augmented (tritones), and those stacks add tension. Over a drone, the whole chord scale sounds like one modal color with motion inside it.",
