    tags: ["voicings", "triads"],
    body: "A **close triad** stacks 1, 3 and 5 within one octave. Each of its three inversions is named by the bass note:\n\n| inversion | bottom → top | top note |\n|---|---|---|\n| root position | 1-3-5 | 5 |\n| 1st inversion | 3-5-1 | 1 |\n| 2nd inversion | 5-1-3 | 3 |\n\nOn three adjacent strings each inversion is one movable shape, so 4 string sets × 3 inversions = **12 shapes per quality**. Going up any string set, the inversions always cycle root → 1st → 2nd → root.\n\nCAGED landmarks (strings 3-2-1): root position = top of the A shape, 1st inversion = top of the E shape, 2nd inversion = top of the D shape (the C shape uses the same three notes).\n\nQualities: maj 1-3-5 · min 1-b3-5 · dim 1-b3-b5 · aug 1-3-#5 · sus4 1-4-5 · sus2 1-2-5.",
