    body: "A **spread triad** is a close triad with its middle voice dropped an octave, the triad version of drop 2. It spans more than an octave, so it needs a skipped string.\n\n| inversion | bottom → top | top note | from close |\n|---|---|---|---|\n| root | 1-5-3 | 3 | 5-1-3 |\n| 1st | 3-1-5 | 5 | 1-3-5 |\n| 2nd | 5-3-1 | 1 | 3-5-1 |\n\nNeighboring voices are a 5th or 6th apart, which gives the open, piano-like sound common in modern jazz guitar (Goodrick's *Advancing Guitarist* covers triads in every spacing on every string set).\n\nPlayability note: root position on 5-3-2 is a big stretch for most roots. The other sets are comfortable.",
