    body: "A **close voicing** fits all four notes of a 7th chord within one octave, with every voice next to its neighbor chord tone: 1-3-5-7, 3-5-7-1, 5-7-1-3, 7-1-3-5.\n\nPianists play these easily. On guitar they usually need wide stretches, because the strings are a 4th apart and close voicings pack seconds and thirds together. The **drop voicings** solve this by moving one or two voices down an octave.\n\nEvery drop voicing (2, 3, 2&4, 2&3, 4) keeps the chord tones in the same cyclic order as the close voicing it came from. That is why voice-leading rules work the same in all of them.",
