    tags: ["voicings", "melodic-minor", "harmony"],
    body: "Jazz melodic minor (ascending form: 1 2 b3 4 5 6 7) harmonized in 7ths:\n\n| degree | 7th | triad | mode |\n|---|---|---|---|\n| i | mMaj7 | min | melodic minor |\n| ii | m7 | min | Dorian b2 |\n| bIII | maj7#5 | aug | Lydian augmented |\n| IV | 7 | maj | Lydian dominant |\n| V | 7 | maj | Mixolydian b6 |\n| vi | m7b5 | dim | Locrian ♮2 |\n| vii | m7b5 | dim | altered |\n\nFingerprints: two dominants side by side (IV7, V7), an augmented triad on bIII, two half-diminished chords. The vii mode is used as a **7alt** chord on that root (in C melodic minor, B7alt: D♯ = E♭ is the 3rd).",
