    id: "harmonic-minor-harmony",
    title: "Harmonic minor harmony",
    tags: ["voicings", "harmonic-minor", "harmony"],
    body: "Harmonic minor (1 2 b3 4 5 b6 7) harmonized in 7ths:\n\n| degree | 7th | triad |\n|---|---|---|\n| i | mMaj7 | min |\n| ii | m7b5 | dim |\n| bIII | maj7#5 | aug |\n| iv | m7 | min |\n| V | 7 | maj |\n| bVI | maj7 | maj |\n| vii | dim7 | dim |\n\nThis is the source of the minor ii–V–i (iiø7 → V7b9 → i). The b6 → 7 step is an **augmented 2nd** (three frets), so in harmonic-minor chord scales one voice leaps at each change. vii°7 is a rootless V7b9.",
